// Read every JSON in /data/chatin written in the last 30 minutes,
// pull out the normalized fields, and hand the batch to the next node.
// Pure native: fs + path. No external services.

const fs = require('fs');
const path = require('path');

const CHATIN_DIR = '/data/chatin';
const WINDOW_MS = 30 * 60 * 1000;
const now = Date.now();
const cutoff = now - WINDOW_MS;

let files = [];
try {
  files = fs.readdirSync(CHATIN_DIR).filter(f => f.endsWith('.json'));
} catch (e) {
  return [{ json: { error: 'cannot read CHATIN_DIR', detail: String(e), messages: [] } }];
}

const messages = [];
for (const f of files) {
  const full = path.join(CHATIN_DIR, f);
  let stat, raw, rec;
  try {
    stat = fs.statSync(full);
  } catch (_) { continue; }
  if (stat.mtimeMs < cutoff) continue;
  try {
    raw = fs.readFileSync(full, 'utf8');
    rec = JSON.parse(raw);
  } catch (_) { continue; }
  const n = rec.normalized || {};
  // Fall back to raw payload fields if the older capture format is in use.
  const p = rec.payload || {};
  messages.push({
    file: f,
    captured_at: rec.captured_at,
    sender: n.sender || p.user_name || p.username || 'unknown',
    channel: n.channel || p.channel_name || 'unknown',
    text: n.text || p.text || '',
    post_id: n.post_id || p.post_id || null
  });
}

messages.sort((a, b) => (a.captured_at < b.captured_at ? -1 : 1));

// Hand a single item carrying the batch + summary stats to the next node.
return [{
  json: {
    window_minutes: 30,
    window_start: new Date(cutoff).toISOString(),
    window_end: new Date(now).toISOString(),
    count: messages.length,
    messages,
    // pre-formatted text for the fallback chat message (no Ollama path)
    fallback_summary: messages.length === 0
      ? '_(no captures in the last 30 min)_'
      : messages.map(m => `- ${m.sender}: ${m.text}`).join('\n')
  }
}];

