// Compose the chat message body. Prefer the Ollama summary; fall back to
// the raw list if Ollama failed or returned nothing useful.
const prev = $input.first().json || {};
const scan = $('Scan /data/chatin (last 30 min)').first().json || {};

let body = '';
if (prev && typeof prev.response === 'string' && prev.response.trim().length > 0) {
  body = prev.response.trim();
} else {
  body = scan.fallback_summary || '_(no content)_';
}

const windowLine = `*Chat digest · last 30 min · ${scan.count || 0} message(s)*`;
const text = `${windowLine}\n${body}`;

return [{ json: { text, count: scan.count || 0 } }];

// No new messages in the last 30 min. Stay silent — do not spam the channel.
// Return a small marker so the execution log shows why the run was a no-op.
return [{ json: { skipped: true, reason: 'no-messages-in-window' } }];
